-- Migration 11: versioned dealer import, local postcode matching and EMEA export profile.

create table if not exists postal_codes (
  zip text primary key check (zip ~ '^[0-9]{5}$'),
  city text not null default '',
  latitude double precision not null,
  longitude double precision not null,
  source_version text not null
);

create table if not exists dealers (
  dealer_code text primary key,
  site_code text,
  name text not null,
  address text not null,
  city text not null,
  zip text not null references postal_codes(zip),
  latitude double precision not null,
  longitude double precision not null,
  active boolean not null default true,
  imported_at timestamptz not null default now()
);

create table if not exists dealer_imports (
  id uuid primary key default gen_random_uuid(),
  file_name text not null,
  checksum text not null,
  row_count integer not null,
  inserted_count integer not null,
  updated_count integer not null,
  unchanged_count integer not null,
  deactivated_count integer not null,
  previous_snapshot jsonb not null,
  created_at timestamptz not null default now(),
  rolled_back_at timestamptz
);

create table if not exists event_export_profiles (
  event_id uuid primary key references events(id) on delete cascade,
  constants jsonb not null default '{"COUNTRYCODE":"DE","BRAND":"LEAP","LANGUAGE":"DE","CONSENT_TRUE":"1","CONSENT_FALSE":"0"}'::jsonb,
  model_mapping jsonb not null default '{"b03x":{"code":"485","description":"B03X"},"b05":{"code":"486","description":"B05"},"b10":{"code":"B108","description":"B10"},"c10":{"code":"B118","description":"C10"},"t03":{"code":"489","description":"T03"}}'::jsonb,
  updated_at timestamptz not null default now()
);
update event_export_profiles set constants = constants || '{"CONSENT_TRUE":"1","CONSENT_FALSE":"0"}'::jsonb
where not (constants ? 'CONSENT_TRUE') or not (constants ? 'CONSENT_FALSE');

alter table players add column if not exists dealer_code text references dealers(dealer_code);
alter table players add column if not exists dealer_site_code text;
alter table players add column if not exists dealer_name text;
alter table players add column if not exists dealer_address text;
alter table players add column if not exists dealer_city text;
alter table players add column if not exists dealer_distance_km numeric(8,2);
alter table players add column if not exists dealer_data_version timestamptz;

create index if not exists idx_dealers_active on dealers(active);
create index if not exists idx_players_dealer on players(dealer_code);

