create or replace function public.nearest_dealer_for_zip(p_zip text)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare
  v_postal postal_codes%rowtype;
  v_result json;
begin
  if p_zip is null or p_zip !~ '^[0-9]{5}$' then
    raise exception 'invalid_zip';
  end if;
  select * into v_postal from postal_codes where zip = p_zip;
  if not found then raise exception 'unknown_zip'; end if;

  select json_build_object(
    'dealer_code', d.dealer_code, 'site_code', d.site_code, 'name', d.name,
    'address', d.address, 'city', d.city, 'zip', d.zip,
    'distance_km', round(x.distance_km::numeric, 2),
    'lead_city', v_postal.city, 'data_version', d.imported_at
  ) into v_result
  from dealers d
  cross join lateral (
    select 6371.0088 * 2 * asin(sqrt(
      power(sin(radians(d.latitude - v_postal.latitude) / 2), 2) +
      cos(radians(v_postal.latitude)) * cos(radians(d.latitude)) *
      power(sin(radians(d.longitude - v_postal.longitude) / 2), 2)
    )) as distance_km
  ) x
  where d.active
  order by x.distance_km, d.dealer_code
  limit 1;

  if v_result is null then raise exception 'no_active_dealer'; end if;
  return v_result;
end;
$$;

grant execute on function public.nearest_dealer_for_zip(text) to anon, authenticated;

-- Bestehende Leads erhalten dieselbe reproduzierbare Zuordnung wie neue Leads.
with matches as (
  select p.id, nearest_dealer_for_zip(p.zip) value from players p
  where p.dealer_code is null and p.zip in (select zip from postal_codes)
)
update players p set
  city = matched.value->>'lead_city',
  dealer_code = matched.value->>'dealer_code', dealer_site_code = matched.value->>'site_code',
  dealer_name = matched.value->>'name', dealer_address = matched.value->>'address',
  dealer_city = matched.value->>'city', dealer_distance_km = (matched.value->>'distance_km')::numeric,
  dealer_data_version = (matched.value->>'data_version')::timestamptz
from matches matched where p.id=matched.id;

create or replace function public.import_dealers(
  p_rows jsonb, p_file_name text, p_checksum text,
  p_deactivate_missing boolean, p_staff_pin text
)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare
  v_snapshot jsonb;
  v_inserted integer := 0; v_updated integer := 0; v_unchanged integer := 0;
  v_deactivated integer := 0; v_count integer; v_import_id uuid;
begin
  if p_staff_pin <> '2882' then raise exception 'invalid_pin'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'empty_import'; end if;
  if exists (
    select 1 from jsonb_to_recordset(p_rows) as r(dealer_code text, site_code text, name text, address text, city text, zip text)
    left join postal_codes p on p.zip = r.zip
    where nullif(trim(r.dealer_code),'') is null or nullif(trim(r.name),'') is null
      or nullif(trim(r.address),'') is null or nullif(trim(r.city),'') is null
      or r.zip !~ '^[0-9]{5}$' or p.zip is null
  ) then raise exception 'invalid_dealer_rows'; end if;
  if exists (
    select dealer_code from jsonb_to_recordset(p_rows) as r(dealer_code text)
    group by dealer_code having count(*) > 1
  ) then raise exception 'duplicate_dealer_code'; end if;

  select coalesce(jsonb_agg(to_jsonb(d) order by d.dealer_code), '[]'::jsonb) into v_snapshot from dealers d;

  with incoming as (
    select trim(r.dealer_code) dealer_code, nullif(trim(r.site_code),'') site_code,
      trim(r.name) name, trim(r.address) address, trim(r.city) city, trim(r.zip) zip
    from jsonb_to_recordset(p_rows) as r(dealer_code text, site_code text, name text, address text, city text, zip text)
  )
  select count(*) filter (where d.dealer_code is null),
         count(*) filter (where d.dealer_code is not null and (d.site_code,d.name,d.address,d.city,d.zip,d.active) is distinct from (i.site_code,i.name,i.address,i.city,i.zip,true)),
         count(*) filter (where d.dealer_code is not null and (d.site_code,d.name,d.address,d.city,d.zip,d.active) is not distinct from (i.site_code,i.name,i.address,i.city,i.zip,true))
    into v_inserted, v_updated, v_unchanged
  from incoming i left join dealers d using (dealer_code);

  insert into dealers(dealer_code,site_code,name,address,city,zip,latitude,longitude,active,imported_at)
  select trim(r.dealer_code), nullif(trim(r.site_code),''), trim(r.name), trim(r.address), trim(r.city), trim(r.zip),
         p.latitude, p.longitude, true, now()
  from jsonb_to_recordset(p_rows) as r(dealer_code text, site_code text, name text, address text, city text, zip text)
  join postal_codes p on p.zip = trim(r.zip)
  on conflict (dealer_code) do update set
    site_code=excluded.site_code, name=excluded.name, address=excluded.address,
    city=excluded.city, zip=excluded.zip, latitude=excluded.latitude,
    longitude=excluded.longitude, active=true, imported_at=now()
  where (dealers.site_code,dealers.name,dealers.address,dealers.city,dealers.zip,dealers.active)
    is distinct from (excluded.site_code,excluded.name,excluded.address,excluded.city,excluded.zip,true);

  if p_deactivate_missing then
    update dealers set active=false, imported_at=now()
    where active and dealer_code not in (
      select trim(r.dealer_code) from jsonb_to_recordset(p_rows) as r(dealer_code text)
    );
    get diagnostics v_deactivated = row_count;
  end if;
  v_count := jsonb_array_length(p_rows);
  insert into dealer_imports(file_name,checksum,row_count,inserted_count,updated_count,unchanged_count,deactivated_count,previous_snapshot)
  values (p_file_name,p_checksum,v_count,v_inserted,v_updated,v_unchanged,v_deactivated,v_snapshot)
  returning id into v_import_id;
  return json_build_object('import_id',v_import_id,'rows',v_count,'inserted',v_inserted,'updated',v_updated,'unchanged',v_unchanged,'deactivated',v_deactivated);
end;
$$;

grant execute on function public.import_dealers(jsonb,text,text,boolean,text) to anon, authenticated;

create or replace function public.get_dealer_admin(p_staff_pin text)
returns json
language plpgsql security definer set search_path=public as $$
declare v_result json;
begin
  if p_staff_pin <> '2882' then raise exception 'invalid_pin'; end if;
  select json_build_object(
    'dealers', coalesce((select json_agg(d order by d.dealer_code) from dealers d), '[]'::json),
    'imports', coalesce((select json_agg(i order by i.created_at desc) from (select id,file_name,checksum,row_count,inserted_count,updated_count,unchanged_count,deactivated_count,created_at,rolled_back_at from dealer_imports limit 20) i), '[]'::json)
  ) into v_result;
  return v_result;
end; $$;
grant execute on function public.get_dealer_admin(text) to anon, authenticated;

create or replace function public.rollback_dealer_import(p_import_id uuid, p_staff_pin text)
returns json language plpgsql security definer set search_path=public as $$
declare v_snapshot jsonb; v_count integer;
begin
  if p_staff_pin <> '2882' then raise exception 'invalid_pin'; end if;
  select previous_snapshot into v_snapshot from dealer_imports where id=p_import_id and rolled_back_at is null for update;
  if v_snapshot is null then raise exception 'import_not_found_or_rolled_back'; end if;
  update dealers set active=false;
  insert into dealers(dealer_code,site_code,name,address,city,zip,latitude,longitude,active,imported_at)
  select dealer_code,site_code,name,address,city,zip,latitude,longitude,active,imported_at
  from jsonb_to_recordset(v_snapshot) as r(dealer_code text,site_code text,name text,address text,city text,zip text,latitude double precision,longitude double precision,active boolean,imported_at timestamptz)
  on conflict(dealer_code) do update set site_code=excluded.site_code,name=excluded.name,address=excluded.address,
    city=excluded.city,zip=excluded.zip,latitude=excluded.latitude,longitude=excluded.longitude,
    active=excluded.active,imported_at=excluded.imported_at;
  get diagnostics v_count=row_count;
  update dealer_imports set rolled_back_at=now() where id=p_import_id;
  return json_build_object('restored',v_count);
end; $$;
grant execute on function public.rollback_dealer_import(uuid,text) to anon, authenticated;

create or replace function public.get_export_profile(p_event_id uuid, p_staff_pin text)
returns json language plpgsql security definer set search_path=public as $$
declare v_result json;
begin
  if p_staff_pin <> '2882' then raise exception 'invalid_pin'; end if;
  insert into event_export_profiles(event_id) values(p_event_id) on conflict do nothing;
  select row_to_json(p) into v_result from event_export_profiles p where event_id=p_event_id;
  return v_result;
end; $$;
grant execute on function public.get_export_profile(uuid,text) to anon,authenticated;

create or replace function public.save_export_profile(p_event_id uuid,p_constants jsonb,p_model_mapping jsonb,p_staff_pin text)
returns json language plpgsql security definer set search_path=public as $$
declare v_result json;
begin
  if p_staff_pin <> '2882' then raise exception 'invalid_pin'; end if;
  if jsonb_typeof(p_constants)<>'object' or jsonb_typeof(p_model_mapping)<>'object' then raise exception 'invalid_profile'; end if;
  insert into event_export_profiles(event_id,constants,model_mapping,updated_at) values(p_event_id,p_constants,p_model_mapping,now())
  on conflict(event_id) do update set constants=excluded.constants,model_mapping=excluded.model_mapping,updated_at=now();
  select row_to_json(p) into v_result from event_export_profiles p where event_id=p_event_id;
  return v_result;
end; $$;
grant execute on function public.save_export_profile(uuid,jsonb,jsonb,text) to anon,authenticated;

-- submit_entry keeps its compatible signature, ignores client city and resolves dealer atomically.
create or replace function public.submit_entry(
  p_event_id uuid,p_score integer,p_ghost_overtaken boolean,p_level_reached integer,p_play_duration_s integer,
  p_contact_intent text,p_vehicle_interest text,p_zip text,p_city text,p_first_name text,p_last_name text,p_email text,p_phone text,
  p_consent_stay boolean,p_consent_offers boolean,p_consent_partners boolean,p_terms_accepted boolean,p_terms_version integer,p_entry_source text default 'byod'
) returns json language plpgsql security definer set search_path=public as $$
declare
  v_player_id uuid; v_score_id uuid; v_win_score integer; v_win_ghost boolean; v_is_win boolean:=false;
  v_code text:=null; v_try integer:=0; v_returning boolean:=false; v_email text; v_dealer json;
begin
  if p_terms_accepted is not true then raise exception 'terms_not_accepted'; end if;
  v_dealer := nearest_dealer_for_zip(p_zip);
  select instant_win_score,instant_win_ghost_req into v_win_score,v_win_ghost from events where id=p_event_id;
  if v_win_score is null then raise exception 'event_not_found'; end if;
  v_email:=nullif(lower(trim(p_email)),'');
  if v_email is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_event_id::text||':'||v_email,0));
    select id into v_player_id from players where nullif(lower(trim(email)),'')=v_email and event_id=p_event_id order by created_at limit 1;
  end if;
  if v_player_id is not null then
    v_returning:=true;
    select json_build_object('dealer_code',dealer_code,'site_code',dealer_site_code,'name',dealer_name,
      'address',dealer_address,'city',dealer_city,'distance_km',dealer_distance_km,
      'lead_city',city,'data_version',dealer_data_version)
      into v_dealer from players where id=v_player_id;
    select iw.claim_code into v_code from instant_wins iw join scores s on s.id=iw.score_id
      where iw.event_id=p_event_id and s.player_id=v_player_id order by iw.created_at limit 1;
  else
    v_is_win:=p_score>=v_win_score and (case when v_win_ghost then p_ghost_overtaken else true end);
    insert into players(event_id,contact_intent,vehicle_interest,zip,city,first_name,last_name,email,phone,
      consent_stay_in_touch,consent_better_offers,consent_partners,terms_accepted,terms_version_at_entry,privacy_accepted_at,entry_source,
      dealer_code,dealer_site_code,dealer_name,dealer_address,dealer_city,dealer_distance_km,dealer_data_version)
    values(p_event_id,p_contact_intent,p_vehicle_interest,p_zip,v_dealer->>'lead_city',p_first_name,p_last_name,v_email,p_phone,
      coalesce(p_consent_stay,false),coalesce(p_consent_offers,false),coalesce(p_consent_partners,false),true,p_terms_version,now(),coalesce(p_entry_source,'byod'),
      v_dealer->>'dealer_code',v_dealer->>'site_code',v_dealer->>'name',v_dealer->>'address',v_dealer->>'city',(v_dealer->>'distance_km')::numeric,(v_dealer->>'data_version')::timestamptz)
    returning id into v_player_id;
  end if;
  insert into scores(event_id,player_id,score,ghost_overtaken,level_reached,play_duration_s,is_instant_win)
    values(p_event_id,v_player_id,p_score,coalesce(p_ghost_overtaken,false),coalesce(p_level_reached,1),p_play_duration_s,v_is_win) returning id into v_score_id;
  if v_is_win then loop
    v_try:=v_try+1; v_code:=lpad((floor(random()*10000))::int::text,4,'0');
    begin insert into instant_wins(event_id,score_id,claim_code) values(p_event_id,v_score_id,v_code); exit;
    exception when unique_violation then if v_try>=20 then raise exception 'code_generation_failed'; end if; end;
  end loop; end if;
  return json_build_object('player_id',v_player_id,'score_id',v_score_id,'is_instant_win',v_is_win,'claim_code',v_code,'is_returning',v_returning,'dealer',v_dealer);
end; $$;

grant execute on function public.submit_entry(uuid,integer,boolean,integer,integer,text,text,text,text,text,text,text,text,boolean,boolean,boolean,boolean,integer,text) to anon,authenticated;

create or replace function public.get_lead_export(p_event_id uuid,p_staff_pin text)
returns json language plpgsql security definer set search_path=public as $$
declare v_result json;
begin
  if p_staff_pin <> '2882' then raise exception 'invalid_pin'; end if;
  insert into event_export_profiles(event_id) values(p_event_id) on conflict do nothing;
  select json_build_object(
    'profile',row_to_json(ep),
    'rows',coalesce((
      select json_agg(row_to_json(x) order by x.lead_date) from (
        select p.created_at lead_date,p.first_name,p.last_name,p.zip,p.city,p.email,p.phone,p.contact_intent,p.vehicle_interest,
          p.consent_stay_in_touch,p.consent_better_offers,p.consent_partners,p.terms_version_at_entry,
          p.dealer_code,p.dealer_site_code,p.dealer_name,p.dealer_address,p.dealer_city,p.dealer_distance_km,
          e.name event_name,e.location event_location
        from players p join events e on e.id=p.event_id where p.event_id=p_event_id
      ) x
    ),'[]'::json)
  ) into v_result from event_export_profiles ep where ep.event_id=p_event_id;
  return v_result;
end; $$;
grant execute on function public.get_lead_export(uuid,text) to anon,authenticated;

alter table postal_codes enable row level security;
alter table dealers enable row level security;
alter table dealer_imports enable row level security;
alter table event_export_profiles enable row level security;
revoke all on postal_codes,dealers,dealer_imports,event_export_profiles from anon,authenticated;
